/**
 * Where a person is, and why it is on the profile at all.
 *
 * Two things need it. The clock: `timezone` alone cannot be guessed from a country (the
 * United States spans 29 zones), so the place is what settles it — see src/lib/geo. And
 * the marketplace that is coming: it opens on the *partner's* city, because gifting
 * somebody far away is hard when you do not know anywhere near them. `city_key` is that
 * city's stable identity, generated by the database so it can never disagree with the
 * place it came from.
 *
 * Every column is nullable and all of them are saved together or not at all: an account
 * made before the location pickers has none, keeps working on `timezone`, and can add a
 * place from Couple Settings → Update location. A partner reads the other's row through
 * the existing profile policy, which is what lets the marketplace see the city it needs
 * without a new table.
 */
export interface Profile {
  id: string;
  couple_id: string | null;
  name: string;
  timezone: string;
  /** ISO 3166-1 alpha-2, e.g. 'NG'; null until this person adds a place. */
  country_code: string | null;
  /** 'Nigeria' — the spelling to show, kept even if the dataset re-spells it later. */
  country_name: string | null;
  /** The place dataset's subdivision code, e.g. 'RI' for Rivers; null where there is none. */
  state_code: string | null;
  state_name: string | null;
  /** 'Port Harcourt'. */
  city_name: string | null;
  /**
   * Generated in the database: 'ng/ri/port-harcourt'. Never written by the app, and the
   * key a vendor query will one day be scoped to.
   */
  city_key: string | null;
  /** When this person last said where they are; null with the rest of the place columns. */
  location_updated_at: string | null;
  last_seen_at: string;
  created_at: string;
}

export interface Couple {
  id: string;
  invite_code: string;
  anniversary_date: string | null;
  created_at: string;
  breakup_requested_by: string | null;
  breakup_requested_at: string | null;
}

/** How often an event comes back. 'none' fires once, on its own date. */
export type RepeatFrequency = 'none' | 'weekly' | 'monthly' | 'yearly';

export const REPEAT_FREQUENCIES: RepeatFrequency[] = ['none', 'weekly', 'monthly', 'yearly'];

export interface CoupleEvent {
  id: string;
  couple_id: string;
  /** Account that added it; null if that account was later deleted. */
  created_by: string | null;
  title: string;
  /** Plain `YYYY-MM-DD` calendar date, no timezone. */
  event_date: string;
  repeat_frequency: RepeatFrequency;
  created_at: string;
  updated_at: string;
}

/**
 * The one picture standing in the couple's nook frame. Exactly one row per couple
 * (the couple id is the key): either partner may replace it, and the row's couple
 * never moves (see `couple_photo` in supabase/schema.sql). The file itself lives in
 * the private `couple-photos` bucket and is opened only through short-lived signed
 * URLs.
 */
export interface CouplePhoto {
  couple_id: string;
  /** Storage path, always `photos/{couple_id}/{photo_id}.jpg` in the private bucket. */
  file_path: string;
  /** Who framed it last; null if that account was later deleted. */
  uploaded_by: string | null;
  created_at: string;
  updated_at: string;
}

/**
 * What a message row is for. Only 'text' is produced by the Chat tab today; the Discuss
 * tab will reuse the same log for prompts ('question'), their replies ('answer') and
 * automatic notes ('system').
 */
export type MessageType = 'text' | 'question' | 'answer' | 'system';

export const MESSAGE_TYPES: MessageType[] = ['text', 'question', 'answer', 'system'];

export interface ChatMessage {
  id: string;
  couple_id: string;
  /** Who wrote it; null only for 'system' notes. */
  sender_id: string | null;
  content: string;
  type: MessageType;
  /**
   * The Discuss question this message continues from, set when "Say more" carries a
   * revealed question into the chat. The bubble renders it as a quoted question card
   * and tapping the card reopens the session — the way back to the answers. NULL for
   * ordinary messages.
   */
  session_id: string | null;
  /**
   * The message this one answers, set by swipe-to-reply or the long-press menu. The
   * bubble renders it as a quoted strip and tapping the strip scrolls back to the
   * original. The database only accepts replies inside the same couple, and the id is
   * frozen with the rest of the row. NULL for ordinary messages.
   */
  reply_to_id: string | null;
  created_at: string;
  /** Set when the *other* partner has seen it — the read receipt. */
  read_at: string | null;
  /**
   * Set by the database when the author rewrote the words. The bubble then shows a
   * small "edited" marker next to its time. NULL while the message is unedited.
   */
  edited_at: string | null;
}

/**
 * Where a bubble is in its lifecycle. 'sending' and 'failed' exist only locally while a
 * message is on its way to the database; 'sent' is one check, 'read' is two.
 */
export type MessageDelivery = 'sending' | 'sent' | 'read' | 'failed';

export interface ChatEntry extends ChatMessage {
  delivery: MessageDelivery;
}

export interface UserSession {
  user: {
    id: string;
    email: string;
  };
  profile: Profile | null;
  couple: Couple | null;
  partner: Profile | null;
}

/* ---------------------------------------------------------------------------
   Discuss: one shared question library, and each couple's private sessions.
   The library rows are imported by the app owner from a CSV — never bundled
   here. See supabase/migrations/202610150004_discuss_questions.sql.
   --------------------------------------------------------------------------- */

/**
 * How a question wants to be answered. The database canonicalises whatever the CSV said
 * into these five values; `multi_choice` is the tick-several variant of `choice`.
 */
export type QuestionInputType = 'text' | 'choice' | 'multi_choice' | 'ranking' | 'slider';

export const QUESTION_INPUT_TYPES: QuestionInputType[] = ['text', 'choice', 'multi_choice', 'ranking', 'slider'];

export interface Question {
  /** TEXT in the database: the id belongs to the imported CSV, so it may be any shape. */
  id: string;
  text: string;
  /** Canonical spelling, e.g. 'Home Life'. A CSV can add categories of its own. */
  category: string;
  /** 1 is the lightest, 5 the heaviest. */
  seriousness: number;
  input_type: QuestionInputType;
  /** Option labels for choice / multi_choice / ranking; null for text and slider. */
  options: string[] | null;
  /** 18+: invisible to a couple until both partners turn the category on. */
  is_adult: boolean;
}

export interface QuestionSession {
  id: string;
  couple_id: string;
  question_id: string;
  /** Who tapped "Ask my partner"; null if that account was later deleted. */
  started_by: string | null;
  created_at: string;
  /** Trigger-maintained: how many of the two partners have answered (0, 1 or 2). */
  answer_count: number;
  /** Stamped when the second answer lands — the moment both answers become readable. */
  completed_at: string | null;
}

/**
 * A stored answer: free text, one label, several labels, an ordered list of labels, or a
 * number from 1 to 10. The database checks the shape against the question before it lands.
 */
export type AnswerValue = string | string[] | number;

export interface QuestionAnswer {
  id: string;
  session_id: string;
  user_id: string;
  answer: AnswerValue;
  created_at: string;
}

/**
 * What is left after the reveal: one comment per partner per question. A second thought
 * does not get typed here — it moves to the chat through "Say more"
 * (messages.session_id), where the conversation can go on with the answers one tap away.
 */
export interface AnswerComment {
  id: string;
  session_id: string;
  user_id: string;
  comment: string;
  created_at: string;
  updated_at: string;
}

/**
 * One row per partner. The 18+ category opens only when both partners of a couple have
 * `adult_questions_enabled`, and closes again the moment either of them turns it off.
 */
export interface CoupleSettings {
  couple_id: string;
  user_id: string;
  adult_questions_enabled: boolean;
  updated_at: string;
}

/* ---------------------------------------------------------------------------
   Daily decisions: an undated three-choice question pool. The database
   randomly assigns each couple one question a day that they have never been
   given before; two private partner selections become a shared decision only
   after the selections match.
   --------------------------------------------------------------------------- */

export interface DailyDecisionQuestion {
  /** The pool row's stable identity; a couple is never assigned it twice. */
  id: number;
  question: string;
  /** Exactly three answer labels, in the order the owner uploaded them. */
  options: [string, string, string];
}

export interface DailyDecisionSnapshot {
  today: string;
  question: DailyDecisionQuestion | null;
  /** The caller's selection, always visible to them. */
  my_choice: number | null;
  /** The partner's selection, populated only after both partners have replied. */
  partner_choice: number | null;
  /** Progress can be known before the answer itself is revealed. */
  partner_responded: boolean;
  both_answered: boolean;
  /** A shared decision is final only when both selections are identical. */
  agreed: boolean;
  /** The pool had questions, and this couple has now been given every one. */
  exhausted: boolean;
  /** Pool questions this couple has not been assigned yet, today's excluded. */
  remaining: number;
  /** How many questions the owner has uploaded to the pool in total. */
  total: number;
}

/* ---------------------------------------------------------------------------
   "I miss you": the taps one partner leaves behind while the other is away.
   One row per sender per own calendar day, with the total tapped and how many
   of those the partner has already been shown; the difference is what is
   waiting. See supabase/migrations/202610150016_miss_you.sql.
   --------------------------------------------------------------------------- */

export interface MissYouTap {
  id: string;
  couple_id: string;
  /** Who tapped. The row is that account's own record. */
  sender_id: string;
  /** The sender's own calendar day as `YYYY-MM-DD` — never a UTC guess. */
  tap_date: string;
  /** Every tap of that day, received or not: the "number of taps". */
  tap_count: number;
  /** How many of them the partner has been shown. The reset sets this to `tap_count`. */
  delivered_count: number;
  /** When the partner last opened them; NULL while nothing has been received yet. */
  delivered_at: string | null;
  created_at: string;
  updated_at: string;
}

/* ---------------------------------------------------------------------------
   Together tab: Visits - planned visits with countdown.
   See supabase/migrations/202610180007_together_visits_and_someday_list.sql.
   --------------------------------------------------------------------------- */

export interface Visit {
  id: string;
  couple_id: string;
  start_date: string;
  end_date: string | null;
  location: string | null;
  timezone: string;
  is_tentative: boolean;
  created_by: string | null;
  created_at: string;
  updated_at: string;
}

/* ---------------------------------------------------------------------------
   Together tab: a shared, ordered list of task titles.
   See supabase/migrations/202610180007_together_visits_and_someday_list.sql and
   supabase/migrations/202610180008_someday_details_order_and_visit_link.sql.
   --------------------------------------------------------------------------- */

export interface SomedayItem {
  id: string;
  couple_id: string;
  /** One shared task title, at most 500 characters. */
  text: string;
  /** Legacy notes retained in storage for old rows; the notebook never displays them. */
  details: string | null;
  /** The couple's notebook order; lower values appear nearer the top. */
  sort_order: number;
  /** The day this idea belongs to when linked to a visit, or null while unplanned. */
  visit_date: string | null;
  /**
   * The visit this idea was added to ("Add to our next visit"), or null while it is
   * still only a someday idea. Deleting the visit puts the idea back on the list
   * rather than deleting it.
   */
  visit_id: string | null;
  completed: boolean;
  completed_at: string | null;
  created_by: string | null;
  created_at: string;
  updated_at: string;
}

/* ---------------------------------------------------------------------------
   Epistles: long, sealed letters written to each other, kept apart from the
   chat. A letter is a draft (sealed_at NULL, the sender's alone), then sealed
   (standing in the partner's mailbox with the wax intact), optionally waiting
   for a chosen day (opens_at), and finally opened — the moment it becomes a
   final keepsake for both. See supabase/migrations/202610200001_epistles.sql.
   --------------------------------------------------------------------------- */

export interface Epistle {
  id: string;
  couple_id: string;
  /** Who wrote it. Only they may rework it, and only until it is opened. */
  sender_id: string;
  /** An optional name for the letter, shown on the envelope; at most 80 characters. */
  title: string | null;
  /** The letter itself — long-form on purpose, at most 20,000 characters. */
  body: string;
  /** When it was sealed and sent; NULL while it is still a draft. */
  sealed_at: string | null;
  /** The calendar day before which the partner's seal refuses to break, or NULL for "as soon as they like". */
  opens_at: string | null;
  /** When the partner broke the seal; NULL while it is still waiting. Once set, the letter is final. */
  opened_at: string | null;
  /**
   * The letter this one answers, or NULL while it starts its own correspondence. A
   * chain of answers is simply letters pointing at each other, oldest first — the
   * app walks the links. Set when the reply is drafted, kept through sealing, and
   * only ever cleared while the reply is still a draft. See
   * supabase/migrations/202610210001_epistle_replies.sql.
   */
  reply_to_id: string | null;
  created_at: string;
  updated_at: string;
}
